changeSet.sql:
CREATE TABLE bot_persona ( name VARCHAR(13) NOT NULL, characterid INT NULL, temperament VARCHAR(64) NOT NULL DEFAULT '', speech_style VARCHAR(255) NOT NULL DEFAULT '', backstory TEXT, traits JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (name) ) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;
CREATE TABLE bot_memory ( id INT NOT NULL AUTO_INCREMENT, bot_name VARCHAR(13) NOT NULL, counterparty VARCHAR(13) NOT NULL DEFAULT '', channel VARCHAR(16) NOT NULL DEFAULT 'WHISPER', speaker VARCHAR(8) NOT NULL DEFAULT 'them', content VARCHAR(512) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY bot_memory_recent (bot_name, counterparty, id), CONSTRAINT bot_memory_persona FOREIGN KEY (bot_name) REFERENCES bot_persona (name) ON DELETE CASCADE ) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;
CREATE TABLE bot_goal ( bot_name VARCHAR(13) NOT NULL, goal_type VARCHAR(32) NOT NULL DEFAULT 'IDLE', target VARCHAR(128) NOT NULL DEFAULT '', target_value INT NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (bot_name), CONSTRAINT bot_goal_persona FOREIGN KEY (bot_name) REFERENCES bot_persona (name) ON DELETE CASCADE ) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

changeSet.rollback:
DROP TABLE IF EXISTS bot_memory;
DROP TABLE IF EXISTS bot_goal;
DROP TABLE IF EXISTS bot_persona;
